'use client';

import { Button as ButtonPrimitive } from '@base-ui/react/button';
import { cva, type VariantProps } from 'class-variance-authority';
import React, { type ElementType } from 'react';

import { useGroup } from '@/components/ui/group';
import { Spinner } from '@/components/ui/spinner';
import { Slot } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn, type SharedProps } from '@/registry/base-nova/protoform/lib/utils';

const buttonVariants = cva(
  [
    'group/button inline-flex shrink-0 items-center justify-center',
    'rounded-lg border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap',
    'transition-all outline-none select-none',
    'cursor-pointer',
    'data-[slot=help-trigger]:rounded-full data-[slot=help-trigger]:text-muted-foreground data-[slot=help-trigger]:shadow-none data-[slot=help-trigger]:hover:text-foreground',
    'disabled:pointer-events-none disabled:cursor-not-allowed',
    'disabled:opacity-50',
    'focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50',
    'aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20',
    'dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40',
    'selection:bg-selected selection:text-selected-foreground',
    'active:not-aria-[haspopup]:translate-y-px',
    '[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*="size-"])]:size-4',
  ],
  {
    defaultVariants: {
      size: 'md',
      variant: 'primary',
    },
    variants: {
      size: {
        default: 'h-8 gap-1.5 px-2.5 has-[>svg]:px-2 [&_svg]:size-4',
        rail: 'h-auto w-4 rounded-none p-0',
        icon: 'size-8 [&_svg]:size-4',
        'icon-lg': 'size-9 [&_svg]:size-4',
        'icon-sm': 'size-7 [&_svg]:size-3.5',
        'icon-xs': 'size-6 [&_svg:not([class*="size-"])]:size-3',
        lg: 'h-9 gap-1.5 px-2.5 has-[>svg]:px-2 [&_svg]:size-4',
        md: 'h-8 gap-1.5 px-2.5 has-[>svg]:px-2 [&_svg]:size-4',
        sm: 'h-7 gap-1 px-2.5 text-xs has-[>svg]:px-2 [&_svg]:size-3.5',
        xs: 'h-6 gap-1 px-2 text-xs has-[>svg]:px-1.5 [&_svg]:size-3',
      },
      variant: {
        default: 'bg-primary text-primary-foreground shadow-xs hover:bg-primary/90 active:bg-primary/80',
        rail: 'rounded-none border-0 bg-transparent shadow-none transition-none hover:bg-transparent hover:after:bg-sidebar-border',
        calendar:
          'flex aspect-square size-auto w-full min-w-(--cell-size) flex-col gap-1 bg-transparent leading-none font-normal text-foreground group-data-[focused=true]/day:relative group-data-[focused=true]/day:z-10 group-data-[focused=true]/day:border-selected group-data-[focused=true]/day:ring-3 group-data-[focused=true]/day:ring-selected/50 hover:bg-muted hover:text-foreground active:bg-muted/80 data-[range-end=true]:rounded-md data-[range-end=true]:rounded-r-md data-[range-end=true]:bg-selected data-[range-end=true]:text-selected-foreground data-[range-middle=true]:rounded-none data-[range-middle=true]:bg-accent data-[range-middle=true]:text-accent-foreground data-[range-start=true]:rounded-md data-[range-start=true]:rounded-l-md data-[range-start=true]:bg-selected data-[range-start=true]:text-selected-foreground data-[selected-single=true]:bg-selected data-[selected-single=true]:text-selected-foreground dark:hover:text-accent-foreground [&>span]:text-xs [&>span]:opacity-70',
        accent: [
          'bg-primary text-primary-foreground shadow-xs',
          'hover:bg-primary/90',
          'active:bg-primary/80',
          'disabled:bg-muted disabled:text-muted-foreground',
        ],
        'accent-ghost': [
          'bg-transparent text-primary',
          'hover:bg-primary/10 hover:text-primary',
          'active:bg-primary/15',
          'disabled:text-muted-foreground',
        ],
        'accent-outline': [
          'border !border-primary bg-transparent text-primary shadow-xs',
          'hover:border-primary/80 hover:bg-primary/10',
          'active:border-primary/70 active:bg-primary/15',
          'disabled:border-border disabled:text-muted-foreground',
        ],
        dashed: [
          'border-2 border-dashed !border-primary bg-transparent text-primary',
          'hover:border-primary/80 hover:bg-primary/5',
          'active:bg-primary/10',
          'disabled:border-border disabled:text-muted-foreground',
        ],
        destructive: [
          'bg-destructive text-primary-foreground shadow-xs',
          'hover:bg-destructive/90',
          'active:bg-destructive/80',
          'focus-visible:ring-destructive',
          'disabled:bg-muted disabled:text-muted-foreground',
        ],
        'destructive-ghost': [
          'bg-transparent text-destructive',
          'hover:bg-destructive/10 hover:text-destructive',
          'active:bg-destructive/10',
          'focus-visible:ring-destructive',
          'disabled:text-muted-foreground',
        ],
        'destructive-outline': [
          'border !border-destructive bg-transparent text-destructive shadow-xs',
          'hover:border-destructive/80 hover:bg-destructive/10',
          'active:border-destructive/70 active:bg-destructive/15',
          'focus-visible:ring-destructive',
          'disabled:border-border disabled:text-muted-foreground',
        ],
        ghost: ['bg-transparent text-foreground', 'hover:bg-muted hover:text-foreground', 'active:bg-muted/80'],
        inverse: [
          'bg-foreground text-background shadow-xs',
          'hover:bg-foreground/90',
          'active:bg-foreground/80',
          'disabled:bg-muted disabled:text-muted-foreground',
        ],
        'inverse-ghost': [
          'bg-transparent text-primary-foreground',
          'hover:bg-primary-foreground/10',
          'active:bg-primary-foreground/15',
          'disabled:text-muted-foreground',
        ],
        'inverse-outline': [
          'border !border-primary-foreground bg-transparent text-primary-foreground shadow-xs',
          'hover:border-transparent hover:bg-primary-foreground/10',
          'active:border-transparent active:bg-primary-foreground/15',
          'disabled:border-muted-foreground disabled:text-muted-foreground',
        ],
        link: [
          'text-primary underline-offset-4',
          'hover:text-primary/80 hover:underline',
          'active:text-primary/60',
          'disabled:text-muted-foreground disabled:no-underline',
        ],
        outline: [
          'border border-input bg-background text-foreground shadow-xs',
          'hover:bg-muted hover:text-foreground',
          'active:bg-muted/80',
        ],
        primary: [
          'bg-primary text-primary-foreground shadow-xs',
          'hover:bg-primary/90',
          'active:bg-primary/80',
          undefined,
        ],
        secondary: [
          'bg-primary text-primary-foreground shadow-xs',
          'hover:bg-primary/90',
          'active:bg-primary/80',
          'disabled:bg-muted disabled:text-muted-foreground',
        ],
        'secondary-ghost': [
          'bg-transparent text-secondary-foreground',
          'hover:bg-secondary',
          'active:bg-secondary/80',
          'disabled:text-muted-foreground',
        ],
        'secondary-outline': [
          'border !border-primary-foreground text-secondary-foreground shadow-xs',
          'hover:border-ring hover:bg-secondary/50',
          'active:border-ring active:bg-secondary/80',
          'disabled:border-border disabled:text-muted-foreground',
        ],
      },
    },
  }
);

export type ButtonVariants = VariantProps<typeof buttonVariants>;

export type ButtonProps = ButtonPrimitive.Props &
  ButtonVariants & {
    asChild?: boolean | undefined;
    as?: ElementType | undefined;
    to?: string | undefined;
    icon?: React.ReactNode | undefined;
    isLoading?: boolean | undefined;
    href?: string | undefined;
    target?: string | undefined;
    rel?: string | undefined;
  } & SharedProps;

function ButtonContent({ children, icon, isLoading }: Pick<ButtonProps, 'children' | 'icon' | 'isLoading'>) {
  const content = icon ? (
    <>
      {children}
      {icon}
    </>
  ) : (
    children
  );
  if (isLoading === true) {
    return (
      <>
        <span className="invisible contents">{content}</span>
        <span aria-hidden="true" className="absolute inset-0 flex items-center justify-center">
          <Spinner />
        </span>
      </>
    );
  }
  return content;
}

type ButtonStyleProps = Pick<ButtonProps, 'className' | 'variant' | 'size' | 'icon' | 'isLoading'> & {
  positionClasses: string;
};

function getButtonClasses(
  { className, variant, size, icon, isLoading, positionClasses }: ButtonStyleProps,
  state: ButtonPrimitive.State
) {
  return cn(
    buttonVariants({ size, variant }),
    positionClasses,
    icon && 'gap-2',
    isLoading === true && 'relative',
    typeof className === 'function' ? className(state) : className
  );
}

function getButtonPositionClasses(attached: boolean, position: ReturnType<typeof useGroup>['position']) {
  if (!attached) {
    return 'rounded-lg';
  }
  if (position === 'first') {
    return 'rounded-r-none rounded-l-lg border-r-0';
  }
  if (position === 'last') {
    return 'rounded-r-lg rounded-l-none border-l-0';
  }
  if (position === 'middle') {
    return 'rounded-none border-r-0 border-l-0';
  }
  return 'rounded-lg';
}

function LegacyButton({
  as,
  asChild,
  children,
  className,
  variant,
  size,
  icon,
  isLoading,
  positionClasses,
  disabled,
  style,
  focusableWhenDisabled: _focusableWhenDisabled,
  ...props
}: ButtonProps & { positionClasses: string }) {
  const Component = as ?? Slot;
  const state: ButtonPrimitive.State = { disabled: disabled === true };
  return React.createElement(
    Component,
    {
      ...props,
      className: getButtonClasses({ className, variant, size, icon, isLoading, positionClasses }, state),
      disabled,
      style: typeof style === 'function' ? style(state) : style,
    },
    asChild === true ? (
      children
    ) : (
      <ButtonContent icon={icon} isLoading={isLoading}>
        {children}
      </ButtonContent>
    )
  );
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      testId,
      as,
      to,
      icon,
      isLoading = false,
      disabled,
      children,
      render,
      nativeButton,
      type = 'button',
      ...props
    },
    ref
  ) => {
    const { attached, position } = useGroup();
    const isDisabled = disabled === true || isLoading;
    const positionClasses = getButtonPositionClasses(attached, position);
    const shared = {
      'aria-busy': isLoading === true ? true : undefined,
      'data-loading': isLoading === true ? true : undefined,
      'data-slot': 'button',
      'data-testid': testId,
      disabled: isDisabled,
      ref,
      type,
    } as const;
    const styleProps = { className, variant, size, icon, isLoading, positionClasses };
    if (asChild === true || as !== undefined) {
      return (
        <LegacyButton {...shared} {...props} {...styleProps} as={as} asChild={asChild} to={to}>
          {children}
        </LegacyButton>
      );
    }
    return (
      <ButtonPrimitive
        {...shared}
        {...props}
        className={(state) => getButtonClasses(styleProps, state)}
        nativeButton={nativeButton}
        render={render}
      >
        <ButtonContent icon={icon} isLoading={isLoading}>
          {children}
        </ButtonContent>
      </ButtonPrimitive>
    );
  }
);

Button.displayName = 'Button';

export { Button, buttonVariants };

import { cva, type VariantProps } from 'class-variance-authority';
import { Command as CommandPrimitive } from 'cmdk';
import { ChevronRight, SearchIcon } from 'lucide-react';
import React from 'react';

import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Popover, PopoverAnchor, PopoverContent } from '@/components/ui/popover';
import { Text } from '@/components/ui/typography';
import { cn, type FixedPositionContentProps, type SharedProps } from '@/registry/base-nova/protoform/lib/utils';

const commandVariants = cva('flex size-full flex-col overflow-hidden rounded-md bg-popover text-popover-foreground', {
  defaultVariants: {
    size: 'md',
    variant: 'elevated',
  },
  variants: {
    size: {
      full: 'w-full',
      lg: 'max-w-2xl min-w-[500px]',
      md: 'max-w-lg min-w-[400px] md:min-w-[450px]',
      sm: 'max-w-sm min-w-[300px]',
    },
    variant: {
      dialog:
        '**:data-[slot=command-input-wrapper]:h-12 [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground [&_[cmdk-group]]:px-2 [&_[cmdk-group]:not([hidden])_~[cmdk-group]]:pt-0 [&_[cmdk-input-wrapper]_svg]:size-5 [&_[cmdk-input]]:h-12 [&_[cmdk-item]]:px-2 [&_[cmdk-item]]:py-3 [&_[cmdk-item]_svg]:size-5',
      'multi-select': 'border !border-input px-1 shadow-md',
      elevated: 'border !border-input shadow-md',
      minimal: '',
    },
  },
});

interface CommandProps
  extends React.ComponentProps<typeof CommandPrimitive>,
    VariantProps<typeof commandVariants>,
    SharedProps {}

function Command({ className, variant, size, testId, ...props }: CommandProps) {
  return (
    <CommandPrimitive
      className={cn(commandVariants({ size, variant }), className)}
      data-slot="command"
      data-testid={testId}
      {...props}
    />
  );
}

type CommandDialogProps = Omit<React.ComponentProps<typeof Dialog>, 'children'> &
  Pick<FixedPositionContentProps, 'showOverlay' | 'container' | 'onOpenAutoFocus'> & {
    title?: string;
    description?: string;
    className?: string;
    children?: React.ReactNode;
    showCloseButton?: boolean;
  };

function CommandDialog({
  title = 'Command Palette',
  description = 'Search for a command to run...',
  showCloseButton = false,
  children,
  showOverlay = true,
  container,
  className,
  onOpenAutoFocus,
  ...props
}: CommandDialogProps) {
  const openAutoFocusProps = typeof onOpenAutoFocus === 'function' ? { onOpenAutoFocus } : undefined;

  return (
    <Dialog {...props}>
      <DialogHeader className="sr-only">
        <DialogTitle>{title}</DialogTitle>
        <DialogDescription>{description}</DialogDescription>
      </DialogHeader>
      <DialogContent
        className={cn('overflow-hidden', container && 'absolute', className)}
        container={container}
        showCloseButton={showCloseButton}
        showOverlay={showOverlay}
        {...openAutoFocusProps}
      >
        <Command variant="dialog">{children}</Command>
      </DialogContent>
    </Dialog>
  );
}

function CommandInput({
  className,
  testId,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Input> & SharedProps) {
  return (
    <div className="flex h-9 items-center gap-2 border-b !border-input px-3" data-slot="command-input-wrapper">
      <SearchIcon className="size-4 shrink-0 opacity-50" />
      <CommandPrimitive.Input
        className={cn(
          'flex h-10 w-full rounded-md bg-transparent py-3 text-sm outline-hidden selection:bg-selected selection:text-selected-foreground placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50',
          className
        )}
        data-slot="command-input"
        data-testid={testId}
        {...props}
      />
    </div>
  );
}

function CommandList({
  className,
  variant,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.List> & { variant?: 'multi-select' }) {
  return (
    <CommandPrimitive.List
      className={cn(
        'max-h-[300px] scroll-py-1 overflow-x-hidden overflow-y-auto',
        variant === 'multi-select' && 'px-0 py-1',
        className
      )}
      data-slot="command-list"
      {...props}
    />
  );
}

function CommandEmpty({ ...props }: React.ComponentProps<typeof CommandPrimitive.Empty>) {
  return <CommandPrimitive.Empty className="py-6 text-center text-sm" data-slot="command-empty" {...props} />;
}

function CommandGroup({
  className,
  testId,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Group> & SharedProps) {
  return (
    <CommandPrimitive.Group
      className={cn(
        'overflow-hidden p-1 text-foreground [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-xs [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground',
        className
      )}
      data-slot="command-group"
      data-testid={testId}
      {...props}
    />
  );
}

function CommandSeparator({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.Separator>) {
  return (
    <CommandPrimitive.Separator
      className={cn('-mx-1 h-px bg-border', className)}
      data-slot="command-separator"
      {...props}
    />
  );
}

function CommandItem({
  className,
  testId,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Item> & SharedProps) {
  return (
    <CommandPrimitive.Item
      className={cn(
        "relative flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none data-[disabled=true]:pointer-events-none data-[disabled=true]:text-muted-foreground data-[disabled=true]:opacity-50 data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      data-slot="command-item"
      data-testid={testId}
      {...props}
    />
  );
}

function CommandShortcut({ className, children, ...props }: React.ComponentProps<'span'>) {
  return (
    <Text
      as="span"
      className={cn('ml-auto text-xs tracking-widest text-muted-foreground', className)}
      data-slot="command-shortcut"
      {...props}
    >
      {children}
    </Text>
  );
}

interface CommandSubContextType {
  onOpenChange: (open: boolean) => void;
  open: boolean;
}

const CommandSubContext = React.createContext<CommandSubContextType | undefined>(undefined);

interface CommandSubProps {
  children: React.ReactNode;
  onOpenChange: (open: boolean) => void;
  open: boolean;
}

function CommandSub({ open, onOpenChange, children }: CommandSubProps) {
  const contextValue = React.useMemo(() => ({ onOpenChange, open }), [onOpenChange, open]);
  return (
    <CommandSubContext.Provider value={contextValue}>
      <Popover onOpenChange={onOpenChange} open={open}>
        {children}
      </Popover>
    </CommandSubContext.Provider>
  );
}

interface CommandSubTriggerProps extends React.ComponentProps<typeof CommandPrimitive.Item> {
  inset?: boolean;
}

function CommandSubTrigger({ className, children, inset, ...props }: CommandSubTriggerProps) {
  const ctx = React.useContext(CommandSubContext);

  return (
    <PopoverAnchor asChild>
      <CommandPrimitive.Item
        className={cn(
          "relative flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none data-[disabled=true]:pointer-events-none data-[disabled=true]:text-muted-foreground data-[disabled=true]:opacity-50 data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
          inset === true && 'pl-8',
          className
        )}
        data-slot="command-sub-trigger"
        onSelect={() => ctx?.onOpenChange(true)}
        {...props}
      >
        {children}
        <ChevronRight className="ml-auto size-4" />
      </CommandPrimitive.Item>
    </PopoverAnchor>
  );
}

interface CommandSubContentProps {
  children: React.ReactNode;
  className?: string;
}

function CommandSubContent({ className, children }: CommandSubContentProps) {
  return (
    <PopoverContent
      align="start"
      className={cn('w-fit p-0', className)}
      initialFocus={false}
      side="right"
      sideOffset={4}
    >
      {children}
    </PopoverContent>
  );
}

interface SimpleCommandProps extends SharedProps {
  className?: string;
  emptyMessage?: string;
  groups: Array<{
    heading?: string;
    items: Array<{
      icon?: React.ReactNode;
      label: string;
      shortcut?: string;
      disabled?: boolean;
      onSelect?: () => void;
    }>;
  }>;
  placeholder?: string;
  size?: 'sm' | 'md' | 'lg' | 'full';
}

function SimpleCommand({
  placeholder = 'Type a command or search...',
  emptyMessage = 'No results found.',
  groups,
  size = 'md',
  className,
  testId,
}: SimpleCommandProps) {
  return (
    <Command className={className} size={size} testId={testId}>
      <CommandInput placeholder={placeholder} />
      <CommandList>
        <CommandEmpty>{emptyMessage}</CommandEmpty>
        {groups.map((group, groupIndex) => (
          <React.Fragment
            key={group.heading !== undefined && group.heading !== '' ? group.heading : `group-${groupIndex}`}
          >
            {groupIndex > 0 && <CommandSeparator />}
            <CommandGroup heading={group.heading}>
              {group.items.map((item) => (
                <CommandItem
                  disabled={item.disabled ?? false}
                  key={item.label}
                  {...(item.onSelect ? { onSelect: item.onSelect } : {})}
                >
                  {item.icon}
                  <Text as="span">{item.label}</Text>
                  {item.shortcut !== undefined && item.shortcut !== '' ? (
                    <CommandShortcut>{item.shortcut}</CommandShortcut>
                  ) : null}
                </CommandItem>
              ))}
            </CommandGroup>
          </React.Fragment>
        ))}
      </CommandList>
    </Command>
  );
}

export {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
  CommandShortcut,
  CommandSub,
  CommandSubContent,
  CommandSubTrigger,
  commandVariants,
  SimpleCommand,
};

import { Dialog as DialogPrimitive } from '@base-ui/react/dialog';
import { cva, type VariantProps } from 'class-variance-authority';
import { X } from 'lucide-react';
import type React from 'react';

import { Button } from '@/components/ui/button';
import { usePortalContainer } from '@/registry/base-nova/protoform/hooks/use-portal-container';
import {
  asChildTrigger,
  renderDescription,
  renderWithDataState,
  warnDeprecatedProp,
} from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn, type FixedPositionContentProps, type SharedProps } from '@/registry/base-nova/protoform/lib/utils';

type DialogRootProps = React.ComponentProps<typeof DialogPrimitive.Root> & SharedProps;

function Dialog({ testId, onOpenChange, ...props }: DialogRootProps) {
  return <DialogPrimitive.Root data-slot="dialog" data-testid={testId} onOpenChange={onOpenChange} {...props} />;
}

type DialogTriggerProps = React.ComponentProps<typeof DialogPrimitive.Trigger> & {
  asChild?: boolean;
};

function DialogTrigger({ className, ...props }: DialogTriggerProps) {
  return (
    <DialogPrimitive.Trigger
      className={(state) => cn('cursor-pointer', typeof className === 'function' ? className(state) : className)}
      data-slot="dialog-trigger"
      {...asChildTrigger(props)}
    />
  );
}

function DialogPortal({ ...props }: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return <DialogPrimitive.Portal data-slot="dialog-portal" {...props} />;
}

type DialogCloseProps = React.ComponentProps<typeof DialogPrimitive.Close> & {
  asChild?: boolean;
};

function DialogClose({ ...props }: DialogCloseProps) {
  return <DialogPrimitive.Close data-slot="dialog-close" {...asChildTrigger(props)} />;
}

function DialogOverlay({ className, ...props }: React.ComponentProps<typeof DialogPrimitive.Backdrop>) {
  return (
    <DialogPrimitive.Backdrop
      className={(state) =>
        cn(
          'fixed inset-0 z-50 bg-black/40 backdrop-blur-xs fill-mode-forwards data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:animate-in data-[state=open]:fade-in-0',
          typeof className === 'function' ? className(state) : className
        )
      }
      data-slot="dialog-overlay"
      render={renderWithDataState('div')}
      {...props}
    />
  );
}

const dialogContentVariants = cva(
