    maxDisplay?: number;
    searchable?: boolean;
    width?: 'sm' | 'md' | 'lg' | 'xl' | 'full' | 'auto';
    emptyState?: React.ReactNode;
  };
const widthClasses = { auto: 'w-auto', full: 'w-full', lg: 'w-80', md: 'w-64', sm: 'w-48', xl: 'w-96' };
function SimpleMultiSelect({
  id,
  options,
  value,
  onValueChange,
  onSearch,
  placeholder = 'Select items…',
  className,
  disabled,
  maxCount,
  maxDisplay,
