export function useMirroredOpen<Details extends { isCanceled: boolean }>(
  controlledOpen: boolean | undefined,
  defaultOpen: boolean | undefined,
  onOpenChange: ((open: boolean, details: Details) => void) | undefined
) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen ?? false);
  const isOpen = controlledOpen ?? uncontrolledOpen;
  const handleOpenChange = (open: boolean, details: Details) => {
    onOpenChange?.(open, details);
    if (!details.isCanceled && controlledOpen === undefined) {
      setUncontrolledOpen(open);
    }
  };
  return { handleOpenChange, isOpen };
}

